    r={'seed':args.seed,'scenario':args.scenario,'confirmed_adult_metadata_fixture':args.confirm_adults,'selected_rate':args.rate,'real_days':args.days,'start':'2026-10-28T00:00:00Z','zone':'America/Chicago','source_commit':(json.loads((ROOT/'BUILD_MANIFEST.json').read_text())['source_commit'] if (ROOT/'BUILD_MANIFEST.json').exists() else __import__('subprocess').check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip()),'status':'running','passed':False,'errors':[],'daily':[],'checkpoints':[],'initialization':'Fixed seed and explicit wall clock. Simulation uses production step+field controllers; per-step autosave disabled in deterministic test driver; save/reload checked explicitly.'};r['runtime_sha256']={str(p.relative_to(ROOT)):hashlib.sha256(p.read_bytes()).hexdigest() for p in [ROOT/'server.py',ROOT/'requirements.txt',ROOT/'config.json',ROOT/'Start_Remote_Deck.bat',*sorted((ROOT/'web').rglob('*'))] if p.is_file()};start=time.monotonic();server=http.server.ThreadingHTTPServer(('127.0.0.1',0),functools.partial(Quiet,directory=str(ROOT/'web')));threading.Thread(target=server.serve_forever,daemon=True).start()
