                row=p.evaluate('__icarusSoak.daily()');cal=p.evaluate('__icarusSoak.snapshot().calendar');row['phase42b']=p.evaluate('''()=>{const s=__icarusSoak.snapshot();return {transit_errors:s.transitAudit,relationship_errors:s.relationshipAudit,social_errors:s.socialAudit,lift_trips:s.transit?.lift.completed||0,lift_queue:s.transit?.lift.queue.length||0,relationships:s.crewSocial.relationships||{},private_events:s.crewSocial.privateEvents||[],confirmed_adults:s.crew.filter(p=>p.adult===true).length,habits:Object.fromEntries(Object.entries(s.crewLife.people).map(([n,m])=>[n,m.habits||{}]))};}''');row['phase43']=p.evaluate('''()=>{const s=__icarusSoak.snapshot();return {systems_errors:s.systemsAudit,gravity_errors:s.gravityAudit,systems:s.shipSystems,crew_motion:s.crew.map(p=>({name:p.name,room:p.room,motion:p.gravityMotion,order:p.systemAssignment})),orders:s.world.maintenance.systemOrders};}''');row['phase44']=p.evaluate('''()=>{const s=__icarusSoak.snapshot(),w=s.world.asteroidExploration;return {errors:s.expeditionAudit,visited:w.rooms.filter(r=>r.visited).map(r=>({id:r.id,kind:r.field.kind})),completed:s.expeditionOperations.history.map(h=>({id:h.id,category:h.category,visited:h.visited,newCells:h.newCells,reason:h.reason})),active:s.missions.asteroid?.ops44?{stage:s.missions.asteroid.ops44.stage,node:s.missions.asteroid.ops44.node,signal:s.missions.asteroid.ops44.signal}:null,devices:Object.values(s.fieldEvidence.devices).map(d=>({id:d.id,status:d.status,condition:d.condition,clips:d.clips.length,ring:d.ring.length})),archive_count:s.fieldEvidence.archive.length,archive_frames:s.fieldEvidence.archive.reduce((n,c)=>n+c.frames.length,0),suits:s.teamLog.fieldSuits||{},utilities:w.rooms.filter(r=>r.field.utility).map(r=>({id:r.id,...r.field.utility}))};}''');row['calendar']=cal;row['snapshot_bytes']=p.evaluate('JSON.stringify(__icarusSoak.snapshot()).length');r['daily'].append(row)
